      monitoring: [{ method: "GET", path: "/v1/monitoring/metrics" }, { method: "POST", path: "/v1/monitoring/metrics" }, { method: "POST", path: "/v1/monitoring/complaints" }, { method: "POST", path: "/v1/monitoring/data-shifts" }],
